<?php
declare(strict_types=1); require_once __DIR__.'/auth.php'; require_login(); $pdo=db(); if(!table_exists($pdo,'businesses')) redirect('upgrade_phase2.php'); $msg=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cid=post_int('client_id');$name=post_string('business_name');if($cid&&$name){$st=$pdo->prepare('INSERT INTO businesses(client_id,business_name,legal_name,business_type,tax_identifier) VALUES(?,?,?,?,?)');$st->execute([$cid,$name,post_string('legal_name')?:null,post_string('business_type')?:null,post_string('tax_identifier')?:null]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','businesses',$id,'Business created: '.$name);flash('success','Business created.');}else{flash('success','Client and business name are required.');}redirect('businesses.php');}
$clients=$pdo->query("SELECT id,first_name,last_name FROM clients WHERE deleted_at IS NULL ORDER BY last_name,first_name")->fetchAll();$rows=$pdo->query("SELECT b.*,CONCAT(c.first_name,' ',c.last_name) client_name FROM businesses b JOIN clients c ON c.id=b.client_id ORDER BY b.id DESC LIMIT 200")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Businesses · SPS CRM</title><style>body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1fr 1.6fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px}.field{margin:10px 0}.field label{display:block;font-size:12px;font-weight:bold;margin-bottom:6px}.field input,.field select{width:100%;padding:10px;border:1px solid #d8dfeb;border-radius:8px}.btn{background:#315ee7;color:white;border:0;padding:11px 14px;border-radius:8px;font-weight:bold}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px;border-bottom:1px solid #edf0f5;text-align:left;font-size:13px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Businesses</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="grid"><div class="card"><h2>Add Business</h2><form method="post"><?=csrf_field()?><div class="field"><label>Client</label><select name="client_id" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=e($c['first_name'].' '.$c['last_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Business Name</label><input name="business_name" required></div><div class="field"><label>Legal Name</label><input name="legal_name"></div><div class="field"><label>Business Type</label><input name="business_type"></div><div class="field"><label>Tax Identifier</label><input name="tax_identifier"></div><button class="btn">Create Business</button></form></div><div class="card"><h2>Businesses</h2><table class="table"><tr><th>Business</th><th>Client</th><th>Type</th><th>Tax ID</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['business_name'])?></td><td><?=e($r['client_name'])?></td><td><?=e($r['business_type']?:'—')?></td><td><?=e($r['tax_identifier']?:'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No businesses yet.</td></tr><?php endif;?></table></div></div></main></body></html>
